<style>
  /* Mondrian tokens */
  :root {
    --ink: #0a0a0a;
    --paper: #fafaf7;
    --red: #d40920;
    --blue: #1356a2;
    --yellow: #f7d501;
    --line: 8px;          /* thick black line */
    --line-thin: 5px;
    --gap: 0px;           /* black lines are the borders, not gaps */
    --maxw: 1120px;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  html { scroll-behavior: smooth; }

  body {
    font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
    background: var(--paper);
    color: var(--ink);
    line-height: 1.55;
  }

  .wrap { max-width: var(--maxw); margin: 0 auto; }

  /* ---------- Hero: the painting as layout ---------- */
  .hero {
    max-width: var(--maxw);
    margin: 24px auto 0;
    border: var(--line) solid var(--ink);
    background: var(--ink);
    display: grid;
    grid-template-columns: 1.15fr 0.55fr 2.1fr;
    grid-template-rows: 2.4fr 0.5fr 0.55fr;
    gap: var(--line); /* black gridlines show through */
    min-height: 72vh;
  }
  .cell { background: var(--paper); }

  .hero-title {              /* tall white cell, left */
    grid-column: 1;
    grid-row: 1 / span 3;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: clamp(20px, 4vw, 48px);
  }
  .kicker {
    font-weight: 800;
    font-size: 0.8rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    margin-bottom: 1rem;
  }
  .kicker .dot { color: var(--red); }
  h1 {
    font-weight: 900;
    font-size: clamp(1.9rem, 4.6vw, 3.6rem);
    line-height: 1.04;
    letter-spacing: -0.02em;
    text-transform: uppercase;
  }
  h1 .sep { color: var(--red); }
  .hero-sub {
    margin-top: 1.25rem;
    font-size: clamp(1rem, 1.4vw, 1.15rem);
    max-width: 34ch;
  }
  .hero-cta { margin-top: 2rem; display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }

  .hero-red {                /* large red square, top right */
    grid-column: 2 / span 2;
    grid-row: 1;
    background: var(--red);
  }
  .hero-blue {               /* small blue square, bottom left of the right field */
    grid-column: 2;
    grid-row: 3;
    background: var(--blue);
  }
  .hero-yellow {             /* small yellow rectangle, bottom right */
    grid-column: 3;
    grid-row: 3;
    background: var(--yellow);
  }
  .hero-white { grid-column: 2 / span 2; grid-row: 2; }

  /* ---------- Buttons ---------- */
  .btn {
    display: inline-block;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.95rem;
    text-decoration: none;
    color: var(--ink);
    background: var(--yellow);
    border: var(--line-thin) solid var(--ink);
    padding: 16px 28px;
    box-shadow: 8px 8px 0 var(--ink);
    transition: transform 120ms ease, box-shadow 120ms ease;
  }
  .btn:hover, .btn:focus-visible { transform: translate(3px, 3px); box-shadow: 5px 5px 0 var(--ink); }
  .btn:focus-visible { outline: 3px solid var(--blue); outline-offset: 4px; }
  .btn:active { transform: translate(8px, 8px); box-shadow: 0 0 0 var(--ink); }
  .btn-ghost { background: var(--paper); }
  .btn-light { background: var(--paper); color: var(--ink); }

  /* ---------- Sections as Mondrian blocks ---------- */
  section { border-top: var(--line) solid var(--ink); }
  .band {
    max-width: var(--maxw);
    margin: 0 auto;
    display: grid;

